import{_ as a,o,c as t,a2 as r}from"./chunks/framework.CFOYCmPM.js";const i="/dayz-studio/manual/images/dayz_studio_3d_view.png",m=JSON.parse('{"title":"Chapter 3: World & Map Editing","description":"","frontmatter":{},"headers":[],"relativePath":"guide/world-and-map.md","filePath":"guide/world-and-map.md","lastUpdated":null}'),n={name:"guide/world-and-map.md"};function s(l,e,d,c,p,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="chapter-3-world-map-editing" tabindex="-1">Chapter 3: World &amp; Map Editing <a class="header-anchor" href="#chapter-3-world-map-editing" aria-label="Permalink to &quot;Chapter 3: World &amp; Map Editing&quot;">​</a></h1><p>DayZ Studio provides an authentic 3D environment rendered using direct ODOL mesh parsing. You can build defensive fortifications, place buildings, erase unwanted vanilla objects, and paint foliage without guessing coordinates.</p><hr><h2 id="🧊-the-3d-preview-viewport" tabindex="-1">🧊 The 3D Preview Viewport <a class="header-anchor" href="#🧊-the-3d-preview-viewport" aria-label="Permalink to &quot;🧊 The 3D Preview Viewport&quot;">​</a></h2><p><img src="'+i+'" alt="DayZ Studio 3D Interactive Viewport"></p><h3 id="understanding-coordinates-in-dayz" tabindex="-1">Understanding Coordinates in DayZ <a class="header-anchor" href="#understanding-coordinates-in-dayz" aria-label="Permalink to &quot;Understanding Coordinates in DayZ&quot;">​</a></h3><p>DayZ coordinates use three numbers <code>[X, Y, Z]</code>:</p><ul><li><strong>X (Red Axis):</strong> East / West position across the map.</li><li><strong>Y (Green Axis):</strong> Vertical altitude (height above sea level).</li><li><strong>Z (Blue Axis):</strong> North / South position.</li></ul><hr><h2 id="🛠️-precision-placement-gizmo-modes" tabindex="-1">🛠️ Precision Placement &amp; Gizmo Modes <a class="header-anchor" href="#🛠️-precision-placement-gizmo-modes" aria-label="Permalink to &quot;🛠️ Precision Placement &amp; Gizmo Modes&quot;">​</a></h2><p>Select any placed object to activate its 3D transform gizmo:</p><ul><li><strong>Press <code>1</code> (Translation Gizmo):</strong> Move objects along X, Y, or Z axes.</li><li><strong>Press <code>2</code> (Rotation Gizmo):</strong> Rotate yaw, pitch, and roll.</li><li><strong>Press <code>3</code> (Scale Gizmo):</strong> Adjust prop size.</li></ul><h3 id="essential-snapping-hotkeys" tabindex="-1">Essential Snapping Hotkeys <a class="header-anchor" href="#essential-snapping-hotkeys" aria-label="Permalink to &quot;Essential Snapping Hotkeys&quot;">​</a></h3><ul><li><strong><code>O</code> (Toggle Surface Snapping):</strong> Automatically snaps objects flush to rooftops, floors, walls, and terrain contours.</li><li><strong><code>End</code> (Drop to Ground):</strong> Drops a floating object directly down to the terrain or surface beneath it.</li><li><strong><code>N</code> (Align to Terrain Slope):</strong> Automatically angles the base of your object to match the natural hill inclination.</li><li><strong><code>G</code> (Cycle Grid Snapping):</strong> Cycles through <em>Off ➔ 1m ➔ 5m ➔ 10m ➔ 25m ➔ 50m</em>.</li><li><strong>Hold <code>Shift</code>:</strong> Performs fine rotation in 1-degree increments.</li><li><strong>Hold <code>Ctrl</code>:</strong> Temporarily bypasses snapping for precision micro-adjustments.</li></ul><hr><h2 id="✂️-the-1-click-vanilla-object-eraser" tabindex="-1">✂️ The 1-Click Vanilla Object Eraser <a class="header-anchor" href="#✂️-the-1-click-vanilla-object-eraser" aria-label="Permalink to &quot;✂️ The 1-Click Vanilla Object Eraser&quot;">​</a></h2><p>Building an outpost in a dense forest or clearing an abandoned town traditionally required messy Enforce script coordinates in <code>init.c</code>.</p><p><strong>In DayZ Studio, erasing vanilla objects is instantaneous:</strong></p><ol><li>In the <strong>3D</strong> or <strong>Map</strong> view, click on <strong>any vanilla tree, rock, wall, fence, or building</strong>.</li><li>The object highlights in red.</li><li>Press <strong><code>Delete</code></strong> on your keyboard (or click <strong>Remove</strong> in the Inspector).</li><li>The object immediately disappears!</li></ol><p>Behind the scenes, DayZ Studio automatically compiles an optimized removal block (<code>DSMapEditsData</code>) into your mod. It even recalculates the AI navigation mesh so infected and animals won&#39;t pathfind around an invisible ghost object!</p><hr><h2 id="🎨-prefab-stamps-brushes" tabindex="-1">🎨 Prefab Stamps &amp; Brushes <a class="header-anchor" href="#🎨-prefab-stamps-brushes" aria-label="Permalink to &quot;🎨 Prefab Stamps &amp; Brushes&quot;">​</a></h2><h3 id="saving-prefabs" tabindex="-1">Saving Prefabs <a class="header-anchor" href="#saving-prefabs" aria-label="Permalink to &quot;Saving Prefabs&quot;">​</a></h3><p>Have you constructed the ultimate sandbag checkpoint or survivor tent?</p><ol><li>Select your placed props.</li><li>Right-click and choose <strong>Save as Prefab Stamp</strong> (<code>.dzprefab.json</code>).</li><li>You can now stamp this complete arrangement anywhere on the map with a single click.</li></ol><h3 id="painting-props-with-brushes" tabindex="-1">Painting Props with Brushes <a class="header-anchor" href="#painting-props-with-brushes" aria-label="Permalink to &quot;Painting Props with Brushes&quot;">​</a></h3><p>Use the brush tools to organically populate environments:</p><ul><li><strong>Scatter Brush:</strong> Randomly scatters rocks, fallen trees, or debris with randomized rotation and size.</li><li><strong>Line Brush:</strong> Places barricades, fences, or lighting poles in an even line between two points.</li><li><strong>Ring Brush:</strong> Arranges campfires, defensive perimeters, or spikes in a circle around your base.</li></ul><hr><h2 id="🔥-avoiding-server-lag-the-150m-performance-heatmap" tabindex="-1">🔥 Avoiding Server Lag: The 150m Performance Heatmap <a class="header-anchor" href="#🔥-avoiding-server-lag-the-150m-performance-heatmap" aria-label="Permalink to &quot;🔥 Avoiding Server Lag: The 150m Performance Heatmap&quot;">​</a></h2><p>DayZ synchronizes objects across players in a <strong>150-meter network bubble</strong>. Placing too many complex 3D meshes in one small area can cause player FPS drops and server desync.</p><p>DayZ Studio includes a live <strong>Performance Heatmap</strong>:</p><ul><li><strong>Green:</strong> Optimal performance (&lt;150 objects per 150m bubble).</li><li><strong>Yellow / Orange:</strong> Moderate density (150–350 objects).</li><li><strong>Red:</strong> Warning! High object concentration. Consider reducing clutter or combining props to ensure smooth gameplay for your players.</li></ul>',33)])])}const u=a(n,[["render",s]]);export{m as __pageData,u as default};
